package com.disablewalkhere;

import net.runelite.client.config.*;
import java.awt.Color;

@ConfigGroup("disablewalkhere")
public interface DisableWalkHereConfig extends Config {

	enum DataAction { //Using Enum dropdown to avoid messy in-game import/export/clear menus or a side panel.
		DEFAULT("Select ..."),
		EXPORT("Clipboard Export Region"),
		EXPORT_ALL("Clipboard Export All"),
		IMPORT("Clipboard Import All"),
		CLEAR_ALL("Clear All Tiles"),
		CLEAR_REGION("Clear Region Tiles");

		private final String name;
		DataAction(String name) { this.name = name; }
		@Override public String toString() { return name; }
	}

	@ConfigItem(keyName = "drawX", name = "Draw 'X' Overlay", description = "Draws an X over tiles", position = 1)
	default boolean drawX() { return true; }

	@ConfigItem(keyName = "enableSound", name = "Enable Sound", description = "Play a sound when clicking a disabled tile (Ingame volume must be on)", position = 2)
	default boolean enableSound() { return true; }

	@ConfigItem(
			keyName = "middleClickPaint",
			name = "Enable Shift+Middle-Click Painting",
			description = "Use Shift + Middle Mouse Button to disable/enable",
			position = 3
	)
	default boolean middleClickPaint() {
		return false;
	}

	@ConfigItem(
			keyName = "shiftRightClickMenu",
			name = "Enable Shift+Right-Click Menu",
			description = "Hold Shift and right-click a tile to enable or disable it",
			position = 4
	)
	default boolean shiftRightClickMenu() {
		return true;
	}

	@Alpha
	@ConfigItem(keyName = "tileColor", name = "Outline Color", description = "Tile Border Color", position = 5)
	default Color tileColor() { return new Color(155, 0, 0, 110); }

	@Alpha
	@ConfigItem(keyName = "fillColor", name = "Fill Color", description = "Tile Fill Color", position = 6)
	default Color fillColor() { return new Color(0, 0, 0, 0); }

	@ConfigItem(
			keyName = "dataAction",
			name = "Share",
			description = "Import/Export/Clear Tiles",
			position = 9
	)
	default DataAction dataAction() {
		return DataAction.DEFAULT;
	}

	@Alpha
	@ConfigItem(keyName = "xColor", name = "X Color", description = "Color of the X", position = 7)
	default Color xColor() { return new Color(155, 30, 20, 115); }

	@ConfigItem(
			keyName = "warningSoundId",
			name = "Sound Effect ID",
			description = "Enter an OSRS sound effect ID (Default: 2266)",
			position = 8
	)
	default int warningSoundId() { return 2266; }
}

package com.disablewalkhere;

import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.*;
import javax.inject.Inject;
import java.awt.*;

public class DisableWalkHereOverlay extends Overlay {
    private final Client client;
    private final DisableWalkHerePlugin plugin;
    private final DisableWalkHereConfig config;

    @Inject
    public DisableWalkHereOverlay(Client client, DisableWalkHerePlugin plugin, DisableWalkHereConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {

        if (client.getLocalPlayer() == null) {
            return null;
        }

        WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();

        for (WorldPoint wp : plugin.getDisabledPoints()) {
            if (wp.getPlane() != client.getPlane()) continue;

            if (wp.distanceTo(playerLocation) > 68) continue;

            LocalPoint lp = LocalPoint.fromWorld(client, wp);
            if (lp == null) continue;

            Polygon poly = Perspective.getCanvasTilePoly(client, lp);
            if (poly != null) {

                OverlayUtil.renderPolygon(graphics, poly, config.tileColor(), config.fillColor(), new BasicStroke(2));

                if (config.drawX() && poly.npoints >= 4) { //Make sure points = 4
                    graphics.setColor(config.xColor());
                    drawX(graphics, poly);
                }
            }
        }
        return null;
    }

    private void drawX(Graphics2D graphics, Polygon poly) {
        int x1 = poly.xpoints[0];
        int y1 = poly.ypoints[0];
        int x2 = poly.xpoints[2];
        int y2 = poly.ypoints[2];

        int x3 = poly.xpoints[1];
        int y3 = poly.ypoints[1];
        int x4 = poly.xpoints[3];
        int y4 = poly.ypoints[3];

        graphics.drawLine(x1, y1, x2, y2);
        graphics.drawLine(x3, y3, x4, y4);
    }
}

package com.disablewalkhere;

import com.google.common.base.Strings;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import java.util.concurrent.ConcurrentHashMap;

import javax.inject.Inject;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.util.*;
import java.util.stream.Collectors;

@PluginDescriptor(name = "Disable Walk Here", description = "Disable walking")
public class DisableWalkHerePlugin extends Plugin {
	@Inject
	private Client client;
	@Inject
	private ConfigManager configManager;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private DisableWalkHereOverlay overlay;
	@Inject
	private DisableWalkHereConfig config;
	@Inject
	private Gson gson;
	@Inject
	private ClientThread clientThread;
	@Inject
	private MouseManager mouseManager;
	@Inject
	private DisableWalkHereTilePainter tilePainter;

	@Getter(AccessLevel.PACKAGE)
	private final Set<WorldPoint> disabledPoints = ConcurrentHashMap.newKeySet();
	private static final String CONFIG_GROUP = "disablewalkhere";

	private int[] lastMapRegions;

	@Override
	protected void startUp() {
		overlayManager.add(overlay);
		mouseManager.registerMouseListener(tilePainter);
		lastMapRegions = null;
		loadTiles();
	}

	@Override
	protected void shutDown() {
		overlayManager.remove(overlay);
		mouseManager.unregisterMouseListener(tilePainter);
		disabledPoints.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGGED_IN) {
			lastMapRegions = null; // Force a refresh when logging in
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		WorldView topLevelView = client.getTopLevelWorldView();
		if (topLevelView == null) return;

		int[] currentMapRegions = topLevelView.getMapRegions();

		if (!Arrays.equals(lastMapRegions, currentMapRegions)) {
			// Clone array
			lastMapRegions = currentMapRegions != null ? currentMapRegions.clone() : null;
			loadTiles();
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event) {
		if (!config.shiftRightClickMenu() || !client.isKeyPressed(KeyCode.KC_SHIFT)) {
			return;
		}

		if (!event.getOption().equals("Walk here")) {
			return;
		}

		Tile hoveredTile = client.getSelectedSceneTile();
		if (hoveredTile == null) {
			return;
		}

		final boolean isCurrentTileDisabled = isTileDisabled(hoveredTile);

		client.createMenuEntry(-1)
				.setOption(isCurrentTileDisabled ? "Enable Walk" : "Disable Walk")
				.setTarget("")
				.setType(MenuAction.RUNELITE)
				.onClick(menuEntry -> {
					clientThread.invokeLater(() -> setTileState(hoveredTile, !isCurrentTileDisabled));
				});
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (event.getMenuAction() == MenuAction.WALK || "Walk here".equals(event.getMenuOption())) {
			int localX = event.getParam0();
			int localY = event.getParam1();

			WorldPoint wp = null;
			if (localX >= 0 && localX < Perspective.SCENE_SIZE && localY >= 0 && localY < Perspective.SCENE_SIZE) {
				LocalPoint lp = LocalPoint.fromScene(localX, localY);
				if (lp != null) {
					wp = WorldPoint.fromLocal(client, lp);
				}
			}

			if (wp == null) {
				Tile tile = client.getSelectedSceneTile();
				if (tile != null) {
					wp = WorldPoint.fromLocal(client, tile.getLocalLocation());
				}
			}

			if (wp != null && disabledPoints.contains(wp)) {
				event.consume();
				if (config.enableSound()) {
					client.playSoundEffect(config.warningSoundId());
				}
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!event.getGroup().equals(CONFIG_GROUP) || !event.getKey().equals("dataAction")) return;

		DisableWalkHereConfig.DataAction action;
		try {
			action = DisableWalkHereConfig.DataAction.valueOf(event.getNewValue());
		} catch (Exception e) {
			return;
		}

		if (action == DisableWalkHereConfig.DataAction.DEFAULT) return;

		switch (action) {
			case EXPORT:
				clientThread.invokeLater(() -> handleExport(false));
				break;
			case EXPORT_ALL:
				clientThread.invokeLater(() -> handleExport(true));
				break;
			case IMPORT:
				clientThread.invokeLater(this::handleImport);
				break;
			case CLEAR_REGION:
				clientThread.invokeLater(this::handleClearRegion);
				break;
			case CLEAR_ALL:
				clientThread.invokeLater(this::handleClearAll);
				break;
		}
		clientThread.invokeLater(() -> configManager.setConfiguration(CONFIG_GROUP, "dataAction", DisableWalkHereConfig.DataAction.DEFAULT));
	}

	public boolean isTileDisabled(Tile tile) {
		if (tile == null) return false;
		WorldPoint wp = WorldPoint.fromLocal(client, tile.getLocalLocation());
		return wp != null && disabledPoints.contains(wp);
	}

	public void setTileState(Tile tile, boolean disable) {
		if (tile == null) return;

		WorldPoint wp = WorldPoint.fromLocalInstance(client, tile.getLocalLocation());
		if (wp == null) return;

		int regionId = wp.getRegionID();
		List<DisableWalkHereRegionTile> tiles = new ArrayList<>(getDisabledTiles(regionId));

		DisableWalkHereRegionTile t = new DisableWalkHereRegionTile(wp);

		boolean currentlyDisabled = tiles.contains(t);
		if (currentlyDisabled == disable) return;

		if (disable) tiles.add(t);
		else tiles.remove(t);

		configManager.setConfiguration(CONFIG_GROUP, "region_" + regionId, gson.toJson(tiles));
		loadTiles();
	}

	private void loadTiles() {
		disabledPoints.clear();

		WorldView topLevelView = client.getTopLevelWorldView();
		if (topLevelView == null) {
			return;
		}

		loadTilesForWorldView(topLevelView);

		for (WorldEntity we : topLevelView.worldEntities()) {
			loadTilesForWorldView(we.getWorldView());
		}
	}

	private void loadTilesForWorldView(WorldView wv) {
		int[] regions = wv.getMapRegions();
		if (regions == null) return;

		for (int regionId : regions) {
			List<DisableWalkHereRegionTile> tiles = getDisabledTiles(regionId);

			for (DisableWalkHereRegionTile t : tiles) {
				Collection<WorldPoint> instancePoints = WorldPoint.toLocalInstance(wv, t.toWorldPoint());
				disabledPoints.addAll(instancePoints);
			}
		}
	}

	private List<DisableWalkHereRegionTile> getDisabledTiles(int regionId) {
		String json = configManager.getConfiguration(CONFIG_GROUP, "region_" + regionId);
		if (Strings.isNullOrEmpty(json)) {
			return new ArrayList<>();
		}

		try {
			List<DisableWalkHereRegionTile> parsed = gson.fromJson(json, new TypeToken<List<DisableWalkHereRegionTile>>() {}.getType());
			return parsed != null ? parsed : new ArrayList<>();
		} catch (Exception e) {
			return new ArrayList<>();
		}
	}

	private void handleExport(boolean allRegions) {
		List<DisableWalkHereRegionTile> tilesToExport = new ArrayList<>();
		if (allRegions) {
			for (String key : configManager.getConfigurationKeys(CONFIG_GROUP + ".region_")) {
				String json = configManager.getConfiguration(CONFIG_GROUP, key.replace(CONFIG_GROUP + ".", ""));
				if (!Strings.isNullOrEmpty(json))
					tilesToExport.addAll(gson.fromJson(json, new TypeToken<List<DisableWalkHereRegionTile>>() {
					}.getType()));
			}
		} else if (client.getLocalPlayer() != null) {
			if (client.isInInstancedRegion()) {
				WorldView topLevelView = client.getTopLevelWorldView();
				if (topLevelView != null && topLevelView.getMapRegions() != null) {
					Set<Integer> uniqueRegions = new HashSet<>();
					for (int regionId : topLevelView.getMapRegions()) {
						uniqueRegions.add(regionId);
					}
					for (int regionId : uniqueRegions) {
						tilesToExport.addAll(getDisabledTiles(regionId));
					}
				}
			} else {
				WorldPoint wp = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
				if (wp != null) {
					tilesToExport = getDisabledTiles(wp.getRegionID());
				}
			}
		}
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(gson.toJson(tilesToExport)), null);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Exported " + tilesToExport.size() + " tiles!", "");
	}

	private void handleImport() {
		try {
			String data = (String) Toolkit.getDefaultToolkit().getSystemClipboard().getData(DataFlavor.stringFlavor);

			if (Strings.isNullOrEmpty(data) || data.length() > 200_000) {
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Import failed: Too large or clipboard empty.", "");
				return;
			}

			List<DisableWalkHereRegionTile> importedRaw = gson.fromJson(data, new TypeToken<List<DisableWalkHereRegionTile>>() {}.getType());

			if (importedRaw == null || importedRaw.isEmpty()) {
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Import failed: Invalid format.", "");
				return;
			}

			Set<DisableWalkHereRegionTile> importedUnique = new HashSet<>(importedRaw);

			for (Map.Entry<Integer, List<DisableWalkHereRegionTile>> entry : importedUnique.stream().collect(Collectors.groupingBy(t -> t.regionId)).entrySet()) {
				Set<DisableWalkHereRegionTile> existingSet = new HashSet<>(getDisabledTiles(entry.getKey()));

				for (DisableWalkHereRegionTile t : entry.getValue()) {
					if (t.z < 0 || t.z >= Constants.MAX_Z ||
							t.regionX < 0 || t.regionX >= Constants.REGION_SIZE ||
							t.regionY < 0 || t.regionY >= Constants.REGION_SIZE ||
							t.regionId < 0) {
						continue;
					}
					existingSet.add(t);
				}
				configManager.setConfiguration(CONFIG_GROUP, "region_" + entry.getKey(), gson.toJson(new ArrayList<>(existingSet)));
			}

			loadTiles();
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Tiles Imported.", "");

		} catch (Exception e) {
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Import failed: Not a valid list.", "");
		}
	}

	private void handleClearAll() {
		for (String key : configManager.getConfigurationKeys(CONFIG_GROUP + ".region_")) {
			configManager.unsetConfiguration(CONFIG_GROUP, key.replace(CONFIG_GROUP + ".", ""));
		}
		disabledPoints.clear();
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Cleared all tiles!", "");
	}

	private void handleClearRegion() {
		if (client.getLocalPlayer() == null) {
			return;
		}

		WorldPoint wp = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
		if (wp == null) {
			return;
		}

		int templateRegionId = wp.getRegionID();

		configManager.unsetConfiguration(CONFIG_GROUP, "region_" + templateRegionId);

		loadTiles();

		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Cleared all tiles in region " + templateRegionId + "!", "");
	}

	@Provides
	DisableWalkHereConfig provideConfig(ConfigManager cm) {
		return cm.getConfig(DisableWalkHereConfig.class);
	}
}

package com.disablewalkhere;

import net.runelite.api.Client;
import net.runelite.api.Tile;
import net.runelite.client.input.MouseAdapter;
import javax.inject.Inject;
import java.awt.event.MouseEvent;

public class DisableWalkHereTilePainter extends MouseAdapter {
    private final Client client;
    private final DisableWalkHerePlugin plugin;
    private final DisableWalkHereConfig config;

    private boolean isPainting = false;
    private boolean paintDisable = true;
    private Tile lastPaintedTile = null;

    @Inject
    public DisableWalkHereTilePainter(Client client, DisableWalkHerePlugin plugin, DisableWalkHereConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event) {
        if (config.middleClickPaint() && event.getButton() == MouseEvent.BUTTON2 && event.isShiftDown()) {
            Tile tile = client.getSelectedSceneTile();
            if (tile != null) {
                isPainting = true;
                paintDisable = !plugin.isTileDisabled(tile);
                plugin.setTileState(tile, paintDisable);
                lastPaintedTile = tile;
                event.consume();
            }
        }
        return event;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event) {
        if (event.getButton() == MouseEvent.BUTTON2 && isPainting) {
            isPainting = false;
            lastPaintedTile = null;
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent event) {
        if (isPainting && config.middleClickPaint()) {
            Tile tile = client.getSelectedSceneTile();
            if (tile != null && !tile.equals(lastPaintedTile)) {
                plugin.setTileState(tile, paintDisable);
                lastPaintedTile = tile;
            }
            event.consume();
        }
        return event;
    }
}

package com.disablewalkhere;

import lombok.EqualsAndHashCode;
import net.runelite.api.coords.WorldPoint;

@EqualsAndHashCode
public class DisableWalkHereRegionTile {
    public int regionId, regionX, regionY, z;

    public DisableWalkHereRegionTile(int regionId, int regionX, int regionY, int z) {
        this.regionId = regionId;
        this.regionX = regionX;
        this.regionY = regionY;
        this.z = z;
    }

    public DisableWalkHereRegionTile(WorldPoint wp) {
        this.regionId = wp.getRegionID();
        this.regionX = wp.getRegionX();
        this.regionY = wp.getRegionY();
        this.z = wp.getPlane();
    }

    public WorldPoint toWorldPoint() {
        return WorldPoint.fromRegion(regionId, regionX, regionY, z);
    }
}
